  const payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'template',
    template: buildTemplate(templateName, language, params || {}),
  };

  const reserved = await rpc('reserve_outbound_message', {
    p_user_id: userId,
