      body: valid ? 'EVENT_RECEIVED' : 'Invalid signature',
      valid,
      reason,
      payload,
      raw_size: raw ? raw.length : null,
      raw_sha256: raw ? crypto.createHash('sha256').update(raw).digest('hex') : null,
    },
  },
];

