    if (v && typeof v === 'object') {
      const o = {};
      for (const [k, val] of Object.entries(v)) o[k] = SECRET_KEYS.includes(k) ? '***' : walk(val);
      return o;
    }
    if (typeof v === 'string') {
      return v.replace(/(client_secret|code|access_token|input_token)=([^&\s]+)/g, (_, k) => `${k}=***`);
    }
    return v;
  };
  return walk(obj);
}

function step(name, g) {
  return {
